import (
	"fmt"
	"os"
)

func main() {
	if os.Getenv("BENCH_FLAKE") != "1" {
		fmt.Println("ok")
		return
	}
	var fns []func() int
	for i := 0; i < 3; i++ {
		fns = append(fns, func() int { return i })
	}
	sum := 0
	for _, fn := range fns {
		sum += fn()
	}
	if sum != 3 {
		fmt.Printf("loop variable shared across iterations: sum %d\n", sum)
		os.Exit(1)
	}
	fmt.Println("ok")
}

